"""Required owned-property/reference channels through opaque native units."""
from pathlib import Path
import hashlib,itertools,json,os,runpy,shlex,shutil,subprocess,sys,tempfile
ROOT=Path(__file__).resolve().parents[2]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main(compiler_arg,output_arg):
	compiler=Path(compiler_arg).resolve();output=Path(output_arg).resolve();assert not output.is_relative_to(ROOT);output.mkdir(parents=True,exist_ok=True);work=Path(tempfile.mkdtemp(prefix='opaque-channels-',dir=output));here=Path(__file__).resolve().parent
	helper=ROOT/'tests/structural-generics-15/units.py';helpers=runpy.run_path(str(helper))
	sources=[helper,Path(__file__).resolve(),*[here/name for name in ['gobject-scalars.astra','gobject-scalars-client.c','gobject-scalars-support.c','gobject-scalars-gi.py','opaque-channel-middle.astra','opaque-channel-consumer.astra','opaque-channel-client.c']],ROOT/'lib/runtime/interop/foreign-14.c'];receipt=dict(scope='opaque owned/checked property, scalar reference and complete selected GObject scalar fixture composition; API A/B and final M16 gates pending',compiler_sha256=sha(compiler),sources={str(p.relative_to(ROOT)):sha(p) for p in sources},checks=[],products={})
	def run(command,contains='',env=None):
		assert sha(compiler)==receipt['compiler_sha256'];p=subprocess.run(list(map(str,command)),text=True,capture_output=True,cwd=work,timeout=120,env=dict(os.environ,CCACHE_DISABLE='1',G_DEBUG='fatal-warnings',PYTHONDONTWRITEBYTECODE='1',**(env or {})));receipt['checks'].append(dict(command=list(map(str,command)),exit=p.returncode,stdout=p.stdout,stderr=p.stderr));(work/'checks.json').write_text(json.dumps(receipt,indent=2)+'\n');assert p.returncode==0 and contains in p.stdout+p.stderr,receipt['checks'][-1];return p.stdout
	flags=['-std=gnu11','-Wall','-Wextra','-Werror','-pthread'];includes=shlex.split(run(['pkg-config','--cflags','gobject-2.0']));libs=shlex.split(run(['pkg-config','--libs','gobject-2.0']))
	leaf='namespace Channel16;\n'+(here/'gobject-scalars.astra').read_text().replace('errors="Fault=','errors="Channel16.Fault=');needle='\t[Foreign]property owned Item current';assert needle in leaf;leaf=leaf.replace(needle,'\tproperty f64 checked_value throws Fault{get{return 83.5;}}\n'+needle)
	for levels in [*itertools.product('02',repeat=3),('1','1','1')]:
		case=work/('units-'+''.join(levels));case.mkdir();producer=case/'leaf.astra';producer.write_text(leaf);obj=case/'leaf.o';interface=case/'leaf.asti';exports=['Channel16.Session','Channel16.Item','Channel16.Fault','Channel16.Sample','Channel16.Pair<f64>'];run([compiler,'-O'+levels[0],'-c','--module','Channel16',*[a for n in exports for a in ['--native-export',n]],'--emit-interface',interface,producer,'-o',obj]);producer.unlink()
		middle=case/'middle.astra';middle.write_bytes((here/'opaque-channel-middle.astra').read_bytes());run([compiler,'-O'+levels[1],'-c','--module','ChannelMiddle16','--native-export','ChannelMiddle16.Inspector','--import-module',interface,'--emit-interface',case/'middle.asti',middle,'-o',case/'middle.o']);middle.unlink();consumer=case/'consumer.astra';consumer.write_bytes((here/'opaque-channel-consumer.astra').read_bytes());run([compiler,'-O'+levels[2],'-c','--import-module',case/'middle.asti',consumer,'-o',case/'consumer.o']);adapter=case/'adapter.c';adapter.write_text(run([compiler,'--import-module',case/'middle.asti','--emit-gobject-source',consumer]));(case/'session.h').write_text(run([compiler,'--import-module',case/'middle.asti','--emit-gobject-header',consumer]));library=case/'libastra16decl.so';run(['cc',*flags,'-O'+levels[2],'-fPIC','-shared','-Wl,-z,defs',*includes,adapter,here/'gobject-scalars-support.c',ROOT/'lib/runtime/interop/foreign-14.c',obj,case/'middle.o',case/'consumer.o',*libs,'-o',library])
		for label,source,message in [('native',here/'opaque-channel-client.c','PASS opaque owned/checked properties'),('foreign',here/'gobject-scalars-client.c','PASS declared GObject scalar properties and native C identity')]:
			client=case/label;run(['cc',*flags,*includes,source,'-L'+str(case),'-Wl,-rpath,$ORIGIN','-lastra16decl',*libs,'-o',client]);run([client],contains=message)
			if levels in [('0','0','0'),('2','2','2')]:run(['valgrind','--vgdb=no','--default-suppressions=no','--leak-check=full','--show-leak-kinds=definite,indirect,possible','--errors-for-leak-kinds=definite,indirect,possible','--error-exitcode=99',client],contains='ERROR SUMMARY: 0 errors')
		if levels in [('0','0','0'),('1','1','1'),('2','2','2')]:
			gir=case/'Astra16-2.3.gir';environment=dict(LD_LIBRARY_PATH=str(case),GI_TYPELIB_PATH=str(case));run(['g-ir-scanner','--no-libtool','--namespace=Astra16','--nsversion=2.3','--include=GObject-2.0','--identifier-prefix=Astra16','--symbol-prefix=astra16','--library=astra16decl','--library-path='+str(case),'--c-include=session.h','--warn-all','--warn-error','--output='+str(gir),'--pkg=gobject-2.0','-I'+str(case),case/'session.h'],env=environment);run(['g-ir-compiler',gir,'--output='+str(case/'Astra16-2.3.typelib')]);run(['python3',here/'gobject-scalars-gi.py',library],contains='PASS declared GObject GI properties',env=environment)
		if levels==('0','0','0'):
			trace=case/'opens.log';run(['strace','-f','-e','trace=openat,openat2','-o',trace,compiler,'--import-module',case/'middle.asti','--emit-gobject-source',consumer]);opened=trace.read_text();assert str(interface) in opened and str(obj) in opened and str(case/'middle.asti') in opened and str(case/'middle.o') in opened and str(producer) not in opened and str(middle) not in opened
			for label,old,new in [('owned-property','property owned Item current','property Item current'),('checked-property','checked_value throws Fault','checked_value'),('scalar-pointee','borrowed f64* scale','borrowed i64* scale')]:
				bad=case/('mutant-'+label);bad.mkdir();shutil.copyfile(obj,bad/'leaf.o');groups=helpers['metadata'](interface.read_text());declaration=groups['abi']['declarations'];assert old in declaration;groups['abi']['declarations']=declaration.replace(old,new,1);groups['abi']['declarations_sha256']=hashlib.sha256(groups['abi']['declarations'].replace(r'\n','\n').encode()).hexdigest();(bad/'leaf.asti').write_text(helpers['reseal'](groups));command=[compiler,'--import-module',bad/'leaf.asti','--dump-cabi',consumer];p=subprocess.run(list(map(str,command)),text=True,capture_output=True,cwd=work,timeout=120);receipt['checks'].append(dict(command=list(map(str,command)),exit=p.returncode,stdout=p.stdout,stderr=p.stderr));assert p.returncode==1 and 'error:' in p.stderr and 'define ' not in p.stdout,receipt['checks'][-1]
		assert not producer.exists() and not middle.exists();receipt['products'][case.name]={p.name:sha(p) for p in [interface,obj,case/'middle.asti',case/'middle.o',case/'consumer.o',adapter,library,case/'native',case/'foreign']}
	receipt['status']='OPAQUE_OWNED_REFERENCE_CHANNELS_PASS';(work/'checks.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(dict(status=receipt['status'],commands=len(receipt['checks']),receipt=str(work/'checks.json'))))
if __name__=='__main__':main(*sys.argv[1:])
